(() => {
  const WEIGHTS = { homework: 0.2, quizzes: 0.3, exam: 0.5 };
  const ALLOWED = new Set(["homework", "quizzes", "exam"]);
  function validateInput(input) {
    if (input === null || typeof input !== "object") {
      throw new Error("input must be an object");
    }
    for (const key of Object.keys(input)) {
      if (!ALLOWED.has(key)) {
        throw new Error("unknown field: " + key);
      }
    }
  }
  function list(value) {
    return Array.isArray(value) ? value : [];
  }
  function average(scores) {
    if (scores.length === 0) return 0;
    let sum = 0;
    for (const s of scores) sum += s;
    return sum / scores.length;
  }
  function homeworkAverage(scores) {
    if (scores.length >= 4) {
      const lowest = Math.min(...scores);
      const idx = scores.indexOf(lowest);
      const rest = scores.slice(0, idx).concat(scores.slice(idx + 1));
      return { average: average(rest), dropped: lowest };
    }
    return { average: average(scores), dropped: null };
  }
  function weightedTotal(hw, qz, ex) {
    return WEIGHTS.homework * hw + WEIGHTS.quizzes * qz + WEIGHTS.exam * ex;
  }
  function roundTo1(value) {
    return Math.round(value * 10) / 10;
  }
  function formatDisplay(value) {
    return value.toFixed(1);
  }
  function finalGrade(input) {
    validateInput(input);
    const homework = list(input.homework);
    const quizzes = list(input.quizzes);
    const exam = list(input.exam);
    const hw = homeworkAverage(homework);
    const quizAverage = average(quizzes);
    const examScore = exam.length > 0 ? exam[0] : 0;
    const total = weightedTotal(hw.average, quizAverage, examScore);
    const final = roundTo1(total);
    return { homeworkAverage: hw.average, quizAverage, examScore, final, display: formatDisplay(final), droppedHomework: hw.dropped };
  }
  return { finalGrade };
})()

