build.unitScript:
test("AC-1: four homework scores drop the lowest and the final grade is 70.5", () => {
  const r = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] });
  assert.equal(r.droppedHomework, 70);
  assert.equal(r.homeworkAverage, 90);
  assert.equal(r.quizAverage, 75);
  assert.equal(r.examScore, 60);
  assert.equal(r.final, 70.5);
  assert.equal(r.display, "70.5");
});
test("AC-2: three homework scores are all averaged with no drop and the final grade is 68.5", () => {
  const r = code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] });
  assert.equal(r.droppedHomework, null);
  assert.equal(r.homeworkAverage, 80);
  assert.equal(r.final, 68.5);
  assert.equal(r.display, "68.5");
});
test("AC-3: missing quiz scores count as 0 and the display shows 48.0", () => {
  const r = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] });
  assert.equal(r.quizAverage, 0);
  assert.equal(r.final, 48);
  assert.equal(r.display, "48.0");
});
test("AC-4: final grade 75.983 rounds to 76 and displays as 76.0", () => {
  const r = code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] });
  assert.ok(Math.abs(r.homeworkAverage - 81.6667) < 1e-3);
  assert.equal(r.quizAverage, 70.5);
  assert.equal(r.final, 76);
  assert.equal(r.display, "76.0");
});
test("a tied lowest homework score drops only one copy and empty categories count as 0", () => {
  const r = code.finalGrade({ homework: [70, 90, 70, 90], quizzes: [], exam: [] });
  assert.equal(r.droppedHomework, 70);
  assert.ok(Math.abs(r.homeworkAverage - 83.3333) < 1e-3);
  assert.equal(r.examScore, 0);
  assert.equal(r.final, 16.7);
  assert.equal(r.display, "16.7");
});
test("an input with an extra field throws an unknown field error naming it", () => {
  assert.throws(() => code.finalGrade({ homework: [], quizzes: [], exam: [], bonus: [5] }), /unknown field: bonus/);
});

build.testScript:
test("drops the lowest homework score when there are 4 or more and applies the category weights", function() {
  var actual = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 75, examScore: 60, final: 70.5, display: "70.5", droppedHomework: 70 });
});
test("averages all homework scores and drops nothing when there are fewer than 4", function() {
  var actual = code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 80, quizAverage: 75, examScore: 60, final: 68.5, display: "68.5", droppedHomework: null });
});
test("counts a category with no scores as 0 and shows the final with 1 decimal", function() {
  var actual = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 0, examScore: 60, final: 48, display: "48.0", droppedHomework: 70 });
});
test("rounds a non-halfway final grade to 1 decimal place and shows that decimal", function() {
  var actual = code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] });
  assert.deepEqual(actual, { homeworkAverage: (80 + 80 + 85) / 3, quizAverage: 70.5, examScore: 77, final: 76, display: "76.0", droppedHomework: null });
});
test("drops only one homework score when the lowest score is tied", function() {
  var actual = code.finalGrade({ homework: [60, 60, 80, 100], quizzes: [100], exam: [80] });
  assert.deepEqual(actual, { homeworkAverage: 80, quizAverage: 100, examScore: 80, final: 86, display: "86.0", droppedHomework: 60 });
});
test("averages quizzes with no drop even when there are 4 or more quiz scores", function() {
  var actual = code.finalGrade({ homework: [100], quizzes: [90, 80, 70, 60], exam: [80] });
  assert.deepEqual(actual, { homeworkAverage: 100, quizAverage: 75, examScore: 80, final: 82.5, display: "82.5", droppedHomework: null });
});
test("counts an exam with no score as 0", function() {
  var actual = code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [] });
  assert.deepEqual(actual, { homeworkAverage: 90, quizAverage: 75, examScore: 0, final: 40.5, display: "40.5", droppedHomework: 70 });
});
test("drops only the single lowest homework score when there are more than 4", function() {
  var actual = code.finalGrade({ homework: [40, 50, 60, 70, 80], quizzes: [90], exam: [70] });
  assert.deepEqual(actual, { homeworkAverage: 65, quizAverage: 90, examScore: 70, final: 75, display: "75.0", droppedHomework: 40 });
});

